def signature(rows):
    """Canonical algebraic sum of the three signed ReLU terms."""
    terms = {}
    for sign, row in zip((1, 1, -1), rows):
        row = tuple(int(v) for v in row)
        if not any(row[:-1]):
            if row[-1] <= 0:
                continue
            scale = row[-1]
            key = (0,) * (len(row) - 1) + (1,)
        else:
            scale = math.gcd(*map(abs, row))
            key = tuple(v // scale for v in row)
        terms[key] = terms.get(key, 0) + sign * scale
    return tuple(sorted((k, v) for k, v in terms.items() if v))

