        if not wanted:
            continue

        dependencies = [
            i for i in range(n) if np.any(rows[:, i] != 0)
        ]
        assert all(previous[i] is not None for i in dependencies)
        matches = []

        def consider(op, indices, template):
            if signature(template) == wanted:
                matches.append((op,) + tuple(previous[i] for i in indices))

        for a in dependencies:
            u = basis[a]
            consider("not", (a,), (constant-u, zero, zero))
            consider("not", (a,), (constant, zero, u))

        for a, b in itertools.product(dependencies, repeat=2):
            u, v = basis[a], basis[b]
            s = u + v
            consider("and", (a, b), (s-constant, zero, zero))
            consider("or", (a, b), (s, zero, s-constant))
            consider("xor", (a, b), (s, zero, 2*s-2*constant))
            consider("xor", (a, b), (u-v, v-u, zero))
            consider("nand", (a, b), (constant, zero, s-constant))
            consider("nor", (a, b), (constant, s-constant, s))

        if not matches:
            for a, b, c in itertools.product(dependencies, repeat=3):
                u, v, z = basis[a], basis[b], basis[c]
                s = u + v + z
                consider("majority", (a, b, c),
                         (s-constant, zero, s-2*constant))
                consider("mux", (a, b, c),
                         (u+v-constant, z-u, zero))

        assert matches, (layer, gate, rows.tolist())
        current[10 + gate] = matches[0]

