def boolean_value(expression, bits):
    op = expression[0]
    if op == "input":
        return bool(bits[expression[1]])
    args = [boolean_value(child, bits) for child in expression[1:]]
    if op == "not":
        return not args[0]
    if op == "and":
        return args[0] and args[1]
    if op == "or":
        return args[0] or args[1]
    if op == "xor":
        return args[0] != args[1]
    if op == "nand":
        return not (args[0] and args[1])
    if op == "nor":
        return not (args[0] or args[1])
    if op == "majority":
        return sum(args) >= 2
    if op == "mux":
        return args[1] if args[0] else args[2]
    raise ValueError(op)

